css:
.search-container {
  position: relative;
  width: 100%;
  max-width: 380px;
  padding-top: 24px;
  padding-bottom: 22px;
}

.search-wrapper {
  position: relative;
  display: flex;
  align-items: center;
  background: linear-gradient(145deg, #18181a 0%, #0c0c0b 50%, #141413 100%);
  border: 2px solid #2a2820;
  padding: 0;
  box-shadow:
    0 8px 30px rgba(0, 0, 0, 0.6),
    0 0 0 1px rgba(107, 138, 58, 0.08),
    inset 0 2px 6px rgba(0, 0, 0, 0.5);
  transition: all 0.4s cubic-bezier(0.16, 1, 0.3, 1);
  overflow: hidden;
  box-sizing: border-box;
}

.search-wrapper::before {
  content: "";
  position: absolute;
  top: 0;
  left: 0;
  right: 0;
  height: 2px;
  background: linear-gradient(
    90deg,
    transparent 0%,
    #4a5a2a 15%,
    #8ba859 50%,
    #4a5a2a 85%,
    transparent 100%
  );
  opacity: 0;
  transition: opacity 0.4s ease;
}

.search-wrapper:focus-within::before {
  opacity: 1;
  animation: lineGlow 2s ease-in-out infinite;
}

@keyframes lineGlow {
  0%,
  100% {
    filter: brightness(1);
  }

  50% {
    filter: brightness(1.5);
  }
}

.search-wrapper::after {
  content: "";
  position: absolute;
  inset: 0;
  background: repeating-linear-gradient(
    0deg,
    transparent,
    transparent 3px,
    rgba(0, 0, 0, 0.02) 3px,
    rgba(0, 0, 0, 0.02) 6px
  );
  pointer-events: none;
}

.search-wrapper:focus-within {
  border-color: #4a5a2a;
  transform: translateY(-2px);
  box-shadow:
    0 12px 40px rgba(0, 0, 0, 0.7),
    0 0 30px rgba(107, 138, 58, 0.1),
    0 0 0 1px rgba(107, 138, 58, 0.3),
    inset 0 2px 6px rgba(0, 0, 0, 0.5);
}

.search-wrapper:hover {
  border-color: #3a3830;
}

.search-icon {
  display: flex;
  align-items: center;
  justify-content: center;
  width: 44px;
  height: 44px;
  flex-shrink: 0;
  position: relative;
  background: linear-gradient(
    135deg,
    rgba(42, 40, 32, 0.3) 0%,
    transparent 100%
  );
}

.search-icon::after {
  content: "";
  position: absolute;
  right: 0;
  top: 50%;
  transform: translateY(-50%);
  width: 1px;
  height: 22px;
  background: linear-gradient(180deg, transparent, #3a3830, transparent);
}

.search-icon svg {
  width: 18px;
  height: 18px;
  color: #5a5a4a;
  transition: all 0.4s ease;
}

.search-wrapper:focus-within .search-icon svg {
  color: #8ba859;
  filter: drop-shadow(0 0 8px rgba(139, 168, 89, 0.6));
  animation: iconPulse 2s ease-in-out infinite;
}

@keyframes iconPulse {
  0%,
  100% {
    transform: scale(1);
  }

  50% {
    transform: scale(1.06);
  }
}

.search-input {
  flex: 1;
  background: transparent;
  border: none;
  outline: none;
  color: #e0e0d0;
  font-size: 0.85rem;
  font-family: "Consolas", "Courier New", "Lucida Console", monospace;
  font-weight: 600;
  letter-spacing: 1px;
  padding: 14px 10px;
  box-sizing: border-box;
  text-transform: uppercase;
}

.search-input::placeholder {
  color: #3a3a2a;
  font-weight: 500;
  text-transform: uppercase;
  letter-spacing: 1.5px;
  font-size: 0.75rem;
}

.search-input:focus::placeholder {
  color: #4a5a3a;
}

.search-decoration {
  display: flex;
  align-items: center;
  gap: 5px;
  margin-right: 10px;
  padding: 6px 10px;
  background: linear-gradient(
    135deg,
    rgba(107, 138, 58, 0.12) 0%,
    rgba(107, 138, 58, 0.05) 100%
  );
  border: 1px solid rgba(107, 138, 58, 0.25);
  border-radius: 2px;
  position: relative;
}

.search-decoration::before {
  content: "SPORE";
  position: absolute;
  top: -7px;
  left: 6px;
  font-family: "Consolas", monospace;
  font-size: 0.4rem;
  color: #5a6a3a;
  letter-spacing: 1.5px;
  background: #141413;
  padding: 0 3px;
}

.spore {
  width: 6px;
  height: 6px;
  background: radial-gradient(circle, #a0c060 0%, #6b8a3a 50%, #3a4a1a 100%);
  border-radius: 50%;
  box-shadow:
    0 0 6px rgba(139, 168, 89, 0.5),
    inset 0 -1px 3px rgba(0, 0, 0, 0.3);
  animation: sporePulse 2s ease-in-out infinite;
}

.spore:nth-child(2) {
  animation-delay: 0.3s;
  width: 4px;
  height: 4px;
}

.spore:nth-child(3) {
  animation-delay: 0.6s;
  width: 7px;
  height: 7px;
}

@keyframes sporePulse {
  0%,
  100% {
    opacity: 0.5;
    transform: scale(1);
    box-shadow: 0 0 6px rgba(139, 168, 89, 0.4);
  }

  50% {
    opacity: 1;
    transform: scale(1.3);
    box-shadow:
      0 0 12px rgba(139, 168, 89, 1),
      0 0 20px rgba(139, 168, 89, 0.4);
  }
}

.search-btn {
  display: flex;
  align-items: center;
  justify-content: center;
  width: 44px;
  height: 44px;
  background: linear-gradient(145deg, #3a4a1a 0%, #2a3a10 50%, #1a2a08 100%);
  border: none;
  border-left: 1px solid #4a5a2a;
  cursor: pointer;
  transition: all 0.3s cubic-bezier(0.16, 1, 0.3, 1);
  flex-shrink: 0;
  box-sizing: border-box;
  position: relative;
  overflow: hidden;
}

.search-btn::before {
  content: "";
  position: absolute;
  top: 0;
  left: -100%;
  width: 100%;
  height: 100%;
  background: linear-gradient(
    90deg,
    transparent,
    rgba(139, 168, 89, 0.2),
    transparent
  );
  transition: left 0.5s ease;
}

.search-btn:hover::before {
  left: 100%;
}

.search-btn::after {
  content: "";
  position: absolute;
  inset: 0;
  background: radial-gradient(
    circle at center,
    rgba(139, 168, 89, 0.2) 0%,
    transparent 70%
  );
  opacity: 0;
  transition: opacity 0.3s ease;
}

.search-btn:hover::after {
  opacity: 1;
}

.search-btn svg {
  width: 18px;
  height: 18px;
  color: #8ba859;
  transition: all 0.3s ease;
  position: relative;
  z-index: 1;
}

.search-btn:hover {
  background: linear-gradient(145deg, #4a5a2a 0%, #3a4a1a 50%, #2a3a10 100%);
  box-shadow: inset 0 0 20px rgba(139, 168, 89, 0.12);
}

.search-btn:hover svg {
  color: #c0d080;
  transform: translateX(3px) scale(1.05);
  filter: drop-shadow(0 0 5px rgba(192, 208, 128, 0.5));
}

.search-btn:active {
  transform: scale(0.96);
}

.search-glow {
  position: absolute;
  bottom: -6px;
  left: 50%;
  transform: translateX(-50%);
  width: 85%;
  height: 30px;
  background: radial-gradient(
    ellipse,
    rgba(139, 168, 89, 0.15) 0%,
    transparent 60%
  );
  pointer-events: none;
  opacity: 0;
  transition: opacity 0.5s ease;
  filter: blur(6px);
}

.search-wrapper:focus-within + .search-glow {
  opacity: 1;
}

.search-label {
  position: absolute;
  top: 0;
  left: 0;
  font-family: "Consolas", monospace;
  font-size: 0.55rem;
  color: #4a4a3a;
  text-transform: uppercase;
  letter-spacing: 3px;
  display: flex;
  align-items: center;
  gap: 6px;
  transition: all 0.4s ease;
}

.search-label::before {
  content: "◆";
  font-size: 0.45rem;
  color: #3a4a2a;
  transition: color 0.4s ease;
}

.search-wrapper:focus-within ~ .search-label {
  color: #8ba859;
}

.search-wrapper:focus-within ~ .search-label::before {
  color: #8ba859;
  text-shadow: 0 0 8px rgba(139, 168, 89, 0.8);
}

.search-status {
  position: absolute;
  bottom: 0;
  right: 0;
  font-family: "Consolas", monospace;
  font-size: 0.5rem;
  color: #3a3a2a;
  text-transform: uppercase;
  letter-spacing: 1.5px;
  display: flex;
  align-items: center;
  gap: 6px;
}

.search-status::before {
  content: "";
  width: 5px;
  height: 5px;
  background: #4a5a2a;
  border-radius: 50%;
  box-shadow: 0 0 5px rgba(139, 168, 89, 0.5);
  animation: statusBlink 1.5s ease-in-out infinite;
}

@keyframes statusBlink {
  0%,
  100% {
    opacity: 0.3;
    box-shadow: 0 0 4px rgba(139, 168, 89, 0.3);
  }

  50% {
    opacity: 1;
    box-shadow: 0 0 8px rgba(139, 168, 89, 0.8);
  }
}

.search-corner {
  position: absolute;
  width: 10px;
  height: 10px;
  border: 1px solid #3a3830;
  pointer-events: none;
}

.search-corner-tl {
  top: 20px;
  left: -3px;
  border-right: none;
  border-bottom: none;
}

.search-corner-tr {
  top: 20px;
  right: -3px;
  border-left: none;
  border-bottom: none;
}

.search-corner-bl {
  bottom: 18px;
  left: -3px;
  border-right: none;
  border-top: none;
}

.search-corner-br {
  bottom: 18px;
  right: -3px;
  border-left: none;
  border-top: none;
}
